        txa
        pha
        tya
        pha
        tsx                             ; S points below the saved Y
        lda $0100+4,x                   ; stacked status register (S+1 = Y, S+2 = X, S+3 = A, S+4 = P)
        and #$00                        ; BRK flag test disabled
        beq irq_dispatch
; not executed $1110-$1112
